import { GoogleGenAI, Type } from '@google/genai';
import env from '../../config/env.js';
import logger from '../../utils/logger.js';

// NOTE: The Hindi and Bengali disclaimer strings need native-speaker review.
export const DISCLAIMER_EN =
  'This summary is generated by AI for informational purposes only and does not constitute legal or official advice. Always verify details with the issuing government authority before taking formal action.';

export const DISCLAIMER_HI =
  'यह सारांश केवल जानकारी के उद्देश्य से AI द्वारा तैयार किया गया है और यह कोई कानूनी या आधिकारिक सलाह नहीं है। कोई भी औपचारिक कदम उठाने से पहले संबंधित सरकारी प्राधिकरण से पुष्टि अवश्य करें।';

export const DISCLAIMER_BN =
  'এই সারাংশটি শুধুমাত্র তথ্যের উদ্দেশ্যে AI দ্বারা তৈরি করা হয়েছে এবং এটি কোনও আইনি বা সরকারি পরামর্শ নয়। কোনো আনুষ্ঠানিক পদক্ষেপ নেওয়ার আগে সংশ্লিষ্ট সরকারি কর্তৃপক্ষের কাছ থেকে বিশদ যাচাই করুন।';

export function getDisclaimer(language = 'en') {
  if (language === 'hi') return DISCLAIMER_HI;
  if (language === 'bn') return DISCLAIMER_BN;
  return DISCLAIMER_EN;
}

export const DOCUMENT_RESPONSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    documentType: { type: Type.STRING },
    summary: { type: Type.STRING },
    keyPoints: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    datesAndAmounts: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          label: { type: Type.STRING },
          value: { type: Type.STRING },
        },
        required: ['label', 'value'],
      },
    },
    obligations: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    redFlags: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    nextSteps: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
    },
    unreadable: { type: Type.BOOLEAN },
    lowConfidence: { type: Type.BOOLEAN },
  },
  required: [
    'documentType',
    'summary',
    'keyPoints',
    'datesAndAmounts',
    'obligations',
    'redFlags',
    'nextSteps',
    'unreadable',
    'lowConfidence',
  ],
};

let injectedClient = null;

/**
 * Dependency injection setter for tests (enables passing mock client without real API keys).
 */
export function setGeminiClient(client) {
  injectedClient = client;
}

/**
 * Get active client (injected or freshly constructed from env).
 */
export function getGeminiClient() {
  if (injectedClient) {
    return injectedClient;
  }
  if (!env.geminiApiKey) {
    const err = new Error('Document Simplifier service is not configured on this server.');
    err.statusCode = 503;
    err.code = 'GEMINI_NOT_CONFIGURED';
    throw err;
  }
  return new GoogleGenAI({ apiKey: env.geminiApiKey });
}

/**
 * Hand-written result structure validator.
 * Enforces types, array length limits (<= 10), and string length caps.
 */
export function validateDocumentSummaryResult(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return false;
  }

  if (typeof data.documentType !== 'string' || data.documentType.length > 500) {
    return false;
  }

  if (typeof data.summary !== 'string' || data.summary.length > 2000) {
    return false;
  }

  const validateStringArray = (arr) => {
    if (!Array.isArray(arr) || arr.length > 10) return false;
    return arr.every((item) => typeof item === 'string' && item.length <= 500);
  };

  if (!validateStringArray(data.keyPoints)) return false;
  if (!validateStringArray(data.obligations)) return false;
  if (!validateStringArray(data.redFlags)) return false;
  if (!validateStringArray(data.nextSteps)) return false;

  if (!Array.isArray(data.datesAndAmounts) || data.datesAndAmounts.length > 10) {
    return false;
  }
  for (const item of data.datesAndAmounts) {
    if (!item || typeof item !== 'object') return false;
    if (typeof item.label !== 'string' || item.label.length > 500) return false;
    if (typeof item.value !== 'string' || item.value.length > 500) return false;
  }

  if (typeof data.unreadable !== 'boolean') return false;
  if (typeof data.lowConfidence !== 'boolean') return false;

  return true;
}

/**
 * Sanitizes errors before throwing. Never logs or leaks raw buffers or payload contents.
 */
function mapGeminiError(err) {
  if (err.statusCode === 503 || err.statusCode === 413 || err.statusCode === 400) {
    return err;
  }

  const status =
    err.status ||
    err.statusCode ||
    (String(err.message).includes('429') ? 429 : String(err.message).includes('404') ? 404 : 500);

  if (status === 429) {
    const error = new Error('AI service is currently busy. Please retry in a moment.');
    error.statusCode = 429;
    return error;
  }

  if (status === 404) {
    logger.error('Gemini model error: model not found or not available for this key, check GEMINI_MODEL');
    const error = new Error('Document simplification model is temporarily unavailable.');
    error.statusCode = 502;
    return error;
  }

  logger.error(`Gemini call error: ${err.message || 'unknown error'}`);
  const error = new Error('Failed to analyze document with AI service.');
  error.statusCode = 502;
  return error;
}

